import { useMemo } from "react";

export type IndexEntry = { id: string; term: string; note?: string };

export function EditorialIndexPage({
  entries,
  onOpen,
}: {
  entries: IndexEntry[];
  onOpen?: (id: string) => void;
}) {
  const sections = useMemo(() => {
    const buckets = new Map<string, IndexEntry[]>();
    for (const entry of [...entries].sort((a, b) => a.term.localeCompare(b.term))) {
      const letter = entry.term[0]?.toUpperCase() ?? "#";
      const key = /[A-Z]/.test(letter) ? letter : "#";
      const bucket = buckets.get(key) ?? [];
      bucket.push(entry);
      buckets.set(key, bucket);
    }
    return [...buckets.entries()].sort(([a], [b]) => a.localeCompare(b));
  }, [entries]);

  return (
    <div className="eidx-root">
      <nav className="eidx-jump" aria-label="Alphabet jump">
        {sections.map(([letter]) => (
          <a key={letter} href={`#idx-${letter}`} className="eidx-jump-link">
            {letter}
          </a>
        ))}
      </nav>

      {sections.map(([letter, items]) => (
        <section className="eidx-section" key={letter}>
          <h3 className="eidx-letter" id={`idx-${letter}`}>
            {letter}
          </h3>
          <ul className="eidx-list">
            {items.map((entry) => (
              <li className="eidx-item" key={entry.id}>
                <button type="button" onClick={() => onOpen?.(entry.id)}>
                  <span className="eidx-term">{entry.term}</span>
                  {entry.note ? <span className="eidx-note">{entry.note}</span> : null}
                </button>
              </li>
            ))}
          </ul>
        </section>
      ))}
    </div>
  );
}

