.eidx-root {
  max-width: 1080px;
  margin: 0 auto;
  padding: 32px 24px 64px;
  font-family: 'Source Han Serif', Georgia, serif;
  color: var(--text-strong, #141414);
  background: var(--surface-base, #fdfcf9);
}
.eidx-jump {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  padding: 10px 0;
  background: inherit;
  border-bottom: 2px solid var(--line-strong, #141414);
}
.eidx-jump-link {
  min-width: 22px;
  text-align: center;
  font-size: 11px;
  letter-spacing: 0.06em;
  text-decoration: none;
  color: var(--text-muted, #52525b);
}
.eidx-jump-link:hover {
  color: var(--accent, #b91c1c);
}
.eidx-section {
  display: grid;
  grid-template-columns: 96px 1fr;
  gap: 24px;
  padding: 24px 0;
  border-bottom: 1px solid var(--line-subtle, #e4e4e7);
}
.eidx-letter {
  position: sticky;
  top: 64px;
  align-self: start;
  margin: 0;
  font-size: 56px;
  line-height: 1;
  font-weight: 700;
}
.eidx-list {
  columns: 3 220px;
  column-gap: 32px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.eidx-item {
  break-inside: avoid;
  margin-bottom: 8px;
}
.eidx-item button {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 1px;
  width: 100%;
  padding: 0;
  text-align: left;
  border: none;
  background: none;
  font: inherit;
  color: inherit;
  cursor: pointer;
}
.eidx-term {
  font-size: 14px;
}
.eidx-item button:hover .eidx-term {
  text-decoration: underline;
  text-underline-offset: 3px;
}
.eidx-note {
  font-size: 11px;
  color: var(--text-muted, #71717a);
}
